EN_RONDA = ["asignado", "en_camino", "recogido", "novedad"]


def numerar_rondas(apps, schema_editor):
    """Antes de exigir el orden único: numera 1, 2, 3... los servicios no terminales de cada
    conductor, respetando el orden que ya tuvieran (los que no tenían van al final, por número).
    No borra nada: solo fija el orden de ronda."""
    Servicio = apps.get_model("solicitudes", "Servicio")
    activos = Servicio.objects.filter(estado__in=EN_RONDA, conductor__isnull=False)
    conductores = set(activos.values_list("conductor_id", flat=True))
    for conductor_id in conductores:
        ronda = activos.filter(conductor_id=conductor_id).order_by(
            F("orden_ronda").asc(nulls_last=True), "pk"
        )
        pks = list(ronda.values_list("pk", flat=True))
        # Primero se vacían, para que la numeración nueva no choque con la vieja.
        Servicio.objects.filter(pk__in=pks).update(orden_ronda=None)
        for puesto, pk in enumerate(pks, start=1):
            Servicio.objects.filter(pk=pk).update(orden_ronda=puesto)


